def check(response, symbols):
    import math
    regression = response.get("regression")
    try:
        coverage = float(response.get("coverage", 0))
        values = regression["polynomialValues"]
        if len(values) != 6 or not all(math.isfinite(float(v)) for v in values) or not math.isfinite(coverage):
            raise ValueError()
        x = Symbol("x", real=True)
        curve = Poly(interpolate([(Rational(i, 5), Rational(str(v))) for i, v in enumerate(values)], x), x)
        derivative = curve.diff()
        candidates = [S.Zero, S.One]
        for (lo, hi), multiplicity in derivative.diff().intervals(eps=Rational(1, 10**12)):
            point = (lo + hi) / 2
            if 0 < point < 1:
                candidates.append(point)
        minimum_slope = min(float(derivative.eval(point)) for point in candidates)
        rise = float(curve.eval(1) - curve.eval(0))
    except (KeyError, TypeError, ValueError, PolynomialError):
        return {"score": 0, "feedback": "Draw across the interval to create a finite polynomial fit."}
    if coverage >= 0.9 and minimum_slope >= -1e-3 and rise > 1e-3:
        return {"score": 1, "feedback": "The fitted polynomial is non-decreasing within slope tolerance 0.001 and rises overall."}
    score = 0.2 * min(max(coverage / 0.9, 0), 1) + 0.7 * int(minimum_slope >= -1e-3) + 0.1 * min(max(rise / 0.1, 0), 1)
    return {"score": min(score, 0.99),
            "feedback": "Extend the drawing across the interval and remove decreasing parts; flat portions are allowed."}

def check(response, symbols):
    import math
    try:
        left, right = float(response["left"]), float(response["right"])
        if not all(math.isfinite(v) for v in (left, right)) or not 0 <= left <= right <= 12.5:
            raise ValueError()
    except (KeyError, TypeError, ValueError):
        return {"score": 0, "feedback": "Place both frame edges on the visible graph."}
    target = 2.5
    width = right - left
    error = abs(width - target)
    if error <= 0.03 * target:
        return {"score": 1, "feedback": "The visible frame spans one complete period."}
    score = max(0, 1 - error/target)
    direction = "narrower" if width > target else "wider"
    return {"score": score,
            "feedback": f"Move one handle to make the frame {direction}; align repeated features to judge one cycle."}

