def check(response, symbols):
    P = response["inputs"]["P"]["matrix"]
    seen = []
    row_status = []
    for i in range(P.rows):
        point = tuple(simplify(value) for value in P.row(i))
        real = all(value.is_number is True and value.is_real is True and value.is_finite is True for value in point)
        duplicate = any(all(simplify(a-b) == 0 for a,b in zip(point, previous)) for previous in seen)
        valid = real and simplify(point[1] - 2*point[0]) == 0 and not duplicate
        row_status.append(valid)
        if valid:
            seen.append(point)
    score = sum(row_status) / P.rows if 2 <= P.rows <= 4 else 0
    return {"score": score,
            "feedback": "" if score == 1 else "Use two to four distinct finite real points on y=2x; equivalent coordinates count as duplicates.",
            "assessment": {"P": {"rows": row_status}}}

