def check(response, symbols):
    import math
    configs = [
        (1.00, 0.00, 0.00),
        (0.75, 0.55, 0.20),
        (1.10, -0.70, -0.10),
        (0.85, 1.05, 0.10),
    ]
    variant = int(response.get("variant", -1))
    clicks = response.get("clicks", [])
    if variant < 0 or variant >= len(configs):
        return {"score": 0, "feedback": "The selected function variant is invalid."}
    amplitude, phase, offset = configs[variant]
    targets = []
    k = -2
    while True:
        x = math.pi/2 - phase + 2*math.pi*k
        if x > 8*math.pi:
            break
        if x >= 0:
            targets.append((x, offset + amplitude))
        k += 1
    remaining = [[float(p[0]), float(p[1])] for p in clicks if len(p) == 2]
    matched = 0
    for tx, ty in targets:
        candidates = [
            (i, abs(px-tx) + abs(py-ty))
            for i, (px, py) in enumerate(remaining)
            if abs(px-tx) <= 0.35 and abs(py-ty) <= 0.30
        ]
        if candidates:
            index = min(candidates, key=lambda item: item[1])[0]
            remaining.pop(index)
            matched += 1
    extras = len(remaining)
    score = max(0, (matched - 0.5*extras) / len(targets))
    if matched == len(targets) and extras == 0:
        return {"score": 1, "feedback": "Every visible local maximum is selected."}
    return {
        "score": score,
        "feedback": f"{matched} of {len(targets)} maxima are matched; remove extra points and inspect each crest."
    }

